          b <- unlist(d60.spl.status[idx][[1]][2])
          x <- data[[p]]
          d60.mult.status <- BuildSpline(a=a, b=b, x=x)$y
          if (p == 'dti'){
            d60.mult.status <- ifelse(data$dti == -999, d60.spl.status$noDti, d60.mult.status)
          }
          if (p == "fico"){
            d60.mult.status <- ifelse(data$hasFICOFlag == 0, d60.spl.status$noFico, d60.mult.status)
          }
        }
        # need to interpolate
        else{
          interp = d60.spl.status[p][[1]]$interpAttribute
          n <- length(d60.spl.status[p][[1]]$functions)
          y <- rep(0, times = nrow(data))
          wgt <- rep(0, times = nrow(data))
          interpIdx = d60.mult.df[, interp]
          tmp = rep(0, times = nrow(data))

          a <- unlist(d60.spl.status[p][[1]]$functions[[1]][1])
          b <- unlist(d60.spl.status[p][[1]]$functions[[1]][2])
          x <- data[[p]]
          noFICO <- BuildSpline(a=a, b=b, x=x)$y

          for (i in 2: n){
            a <- unlist(d60.spl.status[p][[1]]$functions[[i]][1])
            b <- unlist(d60.spl.status[p][[1]]$functions[[i]][2])
            x <- data[[p]]
            y <- BuildSpline(a=a, b=b, x=x)$y
            wgt = ifelse(i!=floor(interpIdx) & i!=floor(interpIdx)+1, 0, ifelse(i==floor(interpIdx), 1 - (interpIdx - floor(interpIdx)), interpIdx - floor(interpIdx)))
            tmp = tmp + y * wgt
          }
          d60.mult.status <- tmp
          d60.mult.status <- ifelse(data$hasFICOFlag == 1, d60.mult.status, noFICO)
        }
        d60.mdr.status[[q]] <- d60.mdr.status[[q]] * d60.mult.status        
        if (test){
            mult = paste("d60", q, p, sep = "_")
            if (q == "reperf"){
                pickStatus = paste("pct", "rp", sep = "_") 
            }
            else if (q == "hampMod"){
                pickStatus = paste("pct", "hmod", sep = "_") 
            }
            else if (q == "nonHampMod"){
                pickStatus = paste("pct", "nhmod", sep = "_") 
            }
            else{
                pickStatus = paste("pct", "none", sep = "_") 
            }
            d60.mult.df[[mult]] = d60.mult.status * data[[pickStatus]] * 0.01 * pickD60
        }
      }
    }       
    d60.mdr = d60.mdr * 0.01 * (d60.mdr.status$none*data$pct_none + d60.mdr.status$reperf*data$pct_rp + d60.mdr.status$hampMod*data$pct_hmod + d60.mdr.status$nonHampMod*data$pct_nhmod) * pickD60
    d60.mult.df$cumHpiIndexInterp                          <- NULL
    d60.mult.df$laggedUnemployChangeSinceStatusIndexInterp <- NULL    
    if (!test){
        rm(d60.mult.df, d60.mult.status)    
    }
    
    end_time4 <- Sys.time()
    cat("d60 ", difftime(end_time4, start_time4, units = "mins"), "\n")
  } else {
