  }

  if (! any(is.na(d90.spl)) ) {
    start_time4 <- Sys.time()

    cat("running d90 mdl", "\n")

    pickD90 = ifelse(data$delMonths == 3, 1, 0)
    d90.seasonals <- SeasonalAdjustment(seasonals = d90.spl$seasonalityMultipliers, months = data$monthBucket)
    d90.mdr <- rep(d90.spl$baselineConstant, times=nrow(data)) * d90.seasonals * d90.spl$adjustmentFactor
    param.d90 <- names(d90.spl)[-match(c("baselineConstant", "adjustmentFactor", "seasonalityMultipliers", "cumHpiIndexInterp", "laggedUnemployChangeSinceStatusIndexInterp"), names(d90.spl))]
    d90.mdr.status <- data.frame(matrix(1, nrow = nrow(data), ncol = 4))
    names(d90.mdr.status) <- param.d90
    d90.mult.df <- data.frame(matrix(1, nrow = nrow(data), ncol = 2))
    names(d90.mult.df) <- c("cumHpiIndexInterp", "laggedUnemployChangeSinceStatusIndexInterp")

    # get cumHpi index
    a <- unlist(d90.spl["cumHpiIndexInterp"][[1]][1])
    b <- unlist(d90.spl["cumHpiIndexInterp"][[1]][2])
    x <- data$fico
    d90.mult.df[, "cumHpiIndexInterp"] <- BuildSpline(a=a, b=b, x=x)$y
    # get laggedUnemployChangeSinceStatus index
    a <- unlist(d90.spl["laggedUnemployChangeSinceStatusIndexInterp"][[1]][1])
    b <- unlist(d90.spl["laggedUnemployChangeSinceStatusIndexInterp"][[1]][2])
    x <- data$fico
    d90.mult.df[, "laggedUnemployChangeSinceStatusIndexInterp"] <- BuildSpline(a=a, b=b, x=x)$y

    for (q in param.d90) {
      d90.spl.status  <- d90.spl[[q]]
      d90.mult.status <- rep(1, times=nrow(data))

      if (q == 'none'){
        param.d90.status <- names(d90.spl.status)[-match(c("noFico", "noDti", "monthsSince1", "monthsSince2"),
                                                         names(d90.spl.status))]
      }
      else{
        param.d90.status <- names(d90.spl.status)[-match(c("monthsSince1", "monthsSince2"),
                                                         names(d90.spl.status))]
