          b <- unlist(d90.spl.status[idx][[1]][2])
          x <- data[[p]]
          d90.mult.status <- BuildSpline(a=a, b=b, x=x)$y
          if (p == 'dti'){
            d90.mult.status <- ifelse(data$dti == -999, d90.spl.status$noDti, d90.mult.status)
          }
          if (p == "fico"){
            d90.mult.status <- ifelse(data$hasFICOFlag == 0, d90.spl.status$noFico, d90.mult.status)
          }
        }
        # need to interpolate
        else{
          interp = d90.spl.status[p][[1]]$interpAttribute
          n <- length(d90.spl.status[p][[1]]$functions)
          y <- rep(0, times = nrow(data))
          wgt <- rep(0, times = nrow(data))
          interpIdx = d90.mult.df[, interp]
          tmp = rep(0, times = nrow(data))

          a <- unlist(d90.spl.status[p][[1]]$functions[[1]][1])
          b <- unlist(d90.spl.status[p][[1]]$functions[[1]][2])
          x <- data[[p]]
          noFICO <- BuildSpline(a=a, b=b, x=x)$y

          for (i in 2: n){
            a <- unlist(d90.spl.status[p][[1]]$functions[[i]][1])
            b <- unlist(d90.spl.status[p][[1]]$functions[[i]][2])
            x <- data[[p]]
            y <- BuildSpline(a=a, b=b, x=x)$y
            wgt = ifelse(i!=floor(interpIdx) & i!=floor(interpIdx)+1, 0, ifelse(i==floor(interpIdx), 1 - (interpIdx - floor(interpIdx)), interpIdx - floor(interpIdx)))
            tmp = tmp + y * wgt
          }
          d90.mult.status <- tmp
