        }
        d90.mdr.status[[q]] <- d90.mdr.status[[q]] * d90.mult.status
        if (test){
            mult = paste("d90", q, p, sep = "_")
            if (q == "reperf"){
                pickStatus = paste("pct", "rp", sep = "_") 
            }
            else if (q == "hampMod"){
                pickStatus = paste("pct", "hmod", sep = "_") 
            }
            else if (q == "nonHampMod"){
