    }

    d90.mdr = d90.mdr * 0.01 * (d90.mdr.status$none*data$pct_none + d90.mdr.status$reperf*data$pct_rp + d90.mdr.status$hampMod*data$pct_hmod + d90.mdr.status$nonHampMod*data$pct_nhmod) * pickD90
    d90.mult.df$cumHpiIndexInterp                          <- NULL
    d90.mult.df$laggedUnemployChangeSinceStatusIndexInterp <- NULL    
