    }

    end_time5 <- Sys.time()
    cat("d90 ", difftime(end_time5, start_time5, units = "mins"), "\n")
  } else {
    d90.mdr <- NA
  }

  if (! any(is.na(cure.spl)) ) {
    cat("running cure mdl\n")

    pickD90 = ifelse(data$delMonths == 3, 1, 0)
    param.cure <- names(cure.spl)[-match(c("baselineConstant", "adjustmentFactor"),
                                         names(cure.spl))]
    cure.mult.df <- data.frame(matrix(nrow=nrow(data), ncol=length(param.cure)))
    names(cure.mult.df) <- param.cure
    cure.mdr <- rep(cure.spl$baselineConstant, times=nrow(data))
    stay.mdr <- rep(cure.spl$baselineConstant, times=nrow(data))

    for (p in param.cure) {

      idx <- match(p, names(cure.spl))
      a <- unlist(cure.spl[idx][[1]][1]) # Otherwise R complains about not being able to coerce a list into a double
      b <- unlist(cure.spl[idx][[1]][2])
      x <- data[[p]]
      cure.mult.df[, p] <- BuildSpline(a=a, b=b, x=x)$y
      cure.mdr <- cure.mdr * cure.mult.df[, p]
    }
    stay.mdr <- 1 - cure.mdr

    cure.mdr = cure.mdr * pickD90
    stay.mdr = stay.mdr * pickD90
    cure.mult.df = cure.mult.df * pickD90

    names(cure.mult.df) <- paste(paste("CURE", names(cure.mult.df), sep="_"), version, sep="_")

  } else {
    cure.mdr <- NA
  }

  if (! any(is.na(buyout.spl)) ) {
    start_time6 <- Sys.time()

    cat("running buyout mdl\n")

    buyout.mult.df <- data.frame(matrix(nrow=nrow(data), ncol=4))
    names(buyout.mult.df) <- c("servicerBuyoutIndex", "buyoutIncentiveShift", "BuyoutLowMult", "BuyoutHighMult")
    buyout.mdr <- rep(1, length(data))
    buyout.submdl <- buyout.spl$buyoutIncentive$functions

    # Get index interp
    aServicer <- unlist(buyout.spl["servicerBuyoutIndexInterp"][[1]][1])
    bServicer <- unlist(buyout.spl["servicerBuyoutIndexInterp"][[1]][2])
    xServicer <- data[["servicerBuyoutIndex"]]
    buyout.mult.df[, "servicerBuyoutIndex"] <- BuildSpline(a=aServicer, b=bServicer, x=xServicer)$y

    # Elbow shift
    aElbow <- unlist(buyout.spl["servicerBuyoutIndexElbow"][[1]][1])
    bElbow <- unlist(buyout.spl["servicerBuyoutIndexElbow"][[1]][2])
    buyout.mult.df[, "buyoutIncentiveShift"] <- BuildSpline(a=aElbow, b=bElbow, x=xServicer)$y

    #Buyout Incentive
    x <- data[["buyoutIncentive"]] + buyout.mult.df[["buyoutIncentiveShift"]]

    # Buyout 0 curve
    aLow <- unlist(buyout.submdl[[1]][1])
    bLow <- unlist(buyout.submdl[[1]][2])
    buyout.mult.df[, "BuyoutLowMult"] <- BuildSpline(a=aLow, b=bLow, x=x)$y

    #Buyout 100 curve
    aHigh <- unlist(buyout.submdl[[2]][1])
    bHigh <- unlist(buyout.submdl[[2]][2])
    buyout.mult.df[, "BuyoutHighMult"] <- BuildSpline(a=aHigh, b=bHigh, x=x)$y

    buyout.mdr <- buyout.mult.df[["BuyoutLowMult"]] * (1 - buyout.mult.df[["servicerBuyoutIndex"]]) + buyout.mult.df[["BuyoutHighMult"]] * buyout.mult.df[["servicerBuyoutIndex"]]

    end_time6 <- Sys.time()
    cat("buyout ", difftime(end_time6, start_time6, units = "mins"), "\n")

  } else {
    buyout.mdr <- NA
  }

  if ( any(is.na(d0.spl)) | any(is.na(d30.spl)) | any(is.na(d60.spl)) | any(is.na(cure.spl)) | any(is.na(buyout.spl)) ) {
    all.mdr <- NA
    return(list("pred"=cure.mdr, "mult"=cure.mult.df))
  } else {
    #result.mdr <- (d0.mdr + d30.mdr + d60.mdr + stay.mdr) * buyout.mdr
    #transit.mdr <- d0.mdr + d30.mdr + d60.mdr + stay.mdr*d90.mdr    
    result.mdr <- (d0.mdr + d30.mdr + d60.mdr + stay.mdr) * buyout.mdr
    transit.mdr <- d0.mdr + d30.mdr + d60.mdr + stay.mdr    
    if (test){
        mult.df <- data.frame(cbind(d0.mult.df, d30.mult.df, d60.mult.df, d0.mdr, d30.mdr, d60.mdr, buyout.mult.df, transit.mdr, buyout.mdr, result.mdr))
        #print(mult.df)
        #return(list("pred_all"=all.mdr, "pred_d0"=d0.mdr, "pred_d30"=d30.mdr, "pred_d60"=d60.mdr, "pred_stay"=stay.mdr,
        #            "pred_transition"=transit.mdr, "pred_buyout"=buyout.mdr, mult.df))   
        return (mult.df)
    }
    else{
        return(list("pred_all"=result.mdr, "pred_transition"=transit.mdr, "pred_buyout"=buyout.mdr))    
    }
  }


}
